custom_css:
@import url("https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600&family=Cormorant+Garamond:ital,wght@1,500&display=swap");
@import url("https://cdn.jsdelivr.net/npm/lxgw-wenkai-screen-webfont@1.7.0/style.css");

/* =========================================================
   十二时辰·午·白昼  ·  theme by if love
   No.07/12 · 午时 11:00–13:00 · 核心词：停顿
   ========================================================= */

/* ---------- 01 tokens ---------- */
:root {
  --wu-sky: #3B7DD8;
  --wu-sky-deep: #2F6CC4;
  --wu-ink: #1E3F73;
  --wu-ink-soft: #4A6FA8;
  --wu-cloud: #FFFFFF;
  --wu-mist: #F3F8FF;
  --wu-pale: #DCE9FA;
  --wu-line: #BFD6F5;
  --wu-mid: #A9C6EE;
  --wu-hint: #6F8FC4;
  --wu-snow: #F4F8FE;
  --wu-panel: #E7F0FC;
  --wu-panel-top: #F3F8FF;
  --wu-or: #F08A3C;
  --wu-ye: #F6C534;
  --wu-gr: #5FA548;
  --wu-cream: #FFE7A6;
  --wu-dot-off: rgba(220, 233, 250, .42);
  --wu-veil: rgba(30, 63, 115, .35);
  --wu-glass: rgba(255, 255, 255, .14);

  --wu-font-title: "Noto Serif SC", "Songti SC", "STSong", serif;
  --wu-font-body: "LXGW WenKai Screen", "LXGW WenKai", "Noto Serif SC", "Songti SC", serif;
  --wu-font-latin: "Cormorant Garamond", "Times New Roman", serif;

  --wu-av-char: 164px;
  --wu-av-user: 140px;
  --wu-head-char: 178px;
  --wu-head-user: 146px;
  --wu-gap-top: 34px;

  --wu-frame-char: url("data:image/webp;base64,");
  --wu-frame-user: url("data:image/webp;base64,");
  --wu-banner: url("data:image/webp;base64,");
  --wu-st-daisy-o: url("data:image/webp;base64,");
  --wu-st-daisy-y: url("data:image/webp;base64,");
  --wu-st-sunflower: url("data:image/webp;base64,");
  --wu-st-clover: url("data:image/webp;base64,");
  --wu-st-cloud: url("data:image/webp;base64,");
  --wu-st-sparkle: url("data:image/webp;base64,");
