  --wu-ic-sliders: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Crect x=%223%22 y=%225.2%22 width=%2218%22 height=%221.6%22 rx=%22.8%22/%3E%3Ccircle cx=%229%22 cy=%226%22 r=%222.6%22/%3E%3Crect x=%223%22 y=%2211.2%22 width=%2218%22 height=%221.6%22 rx=%22.8%22/%3E%3Ccircle cx=%2215.5%22 cy=%2212%22 r=%222.6%22/%3E%3Crect x=%223%22 y=%2217.2%22 width=%2218%22 height=%221.6%22 rx=%22.8%22/%3E%3Ccircle cx=%227%22 cy=%2218%22 r=%222.6%22/%3E%3C/svg%3E");
  --wu-ic-plug: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Crect x=%228%22 y=%222%22 width=%221.9%22 height=%225.5%22 rx=%22.9%22/%3E%3Crect x=%2214.1%22 y=%222%22 width=%221.9%22 height=%225.5%22 rx=%22.9%22/%3E%3Cpath d=%22M5.5 7h13v3.5a6.5 6.5 0 0 1-5.6 6.4V22h-1.8v-5.1A6.5 6.5 0 0 1 5.5 10.5z%22/%3E%3C/svg%3E");
