  --wu-ic-cloud: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Ccircle cx=%228%22 cy=%2214%22 r=%224.3%22/%3E%3Ccircle cx=%2213%22 cy=%2210.5%22 r=%225.3%22/%3E%3Ccircle cx=%2217.6%22 cy=%2214.4%22 r=%223.9%22/%3E%3Crect x=%227%22 y=%2213%22 width=%2211%22 height=%225.3%22 rx=%222%22/%3E%3C/svg%3E");
  --wu-ic-clover: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Ccircle cx=%229.6%22 cy=%226.8%22 r=%223.4%22/%3E%3Ccircle cx=%2214.4%22 cy=%226.8%22 r=%223.4%22/%3E%3Ccircle cx=%226.6%22 cy=%2212.2%22 r=%223.4%22/%3E%3Ccircle cx=%229%22 cy=%2216%22 r=%223.4%22/%3E%3Ccircle cx=%2217.4%22 cy=%2212.2%22 r=%223.4%22/%3E%3Ccircle cx=%2215%22 cy=%2216%22 r=%223.4%22/%3E%3Crect x=%2211.2%22 y=%2215%22 width=%221.6%22 height=%227.5%22 rx=%22.8%22/%3E%3C/svg%3E");
  --wu-ic-sunflower: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Ccircle cx=%2212%22 cy=%2212%22 r=%224.6%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%280.0 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%2825.7 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%2851.4 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%2877.1 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28102.9 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28128.6 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28154.3 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28180.0 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28205.7 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28231.4 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28257.1 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28282.9 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28308.6 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%224.4%22 rx=%221.5%22 ry=%223.4%22 transform=%22rotate%28334.3 12 12%29%22/%3E%3C/svg%3E");
  --wu-ic-daisy: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Ccircle cx=%2212%22 cy=%2212%22 r=%222.8%22/%3E%3Cellipse cx=%2212%22 cy=%225.4%22 rx=%222.1%22 ry=%224.4%22 transform=%22rotate%280.0 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%225.4%22 rx=%222.1%22 ry=%224.4%22 transform=%22rotate%2845.0 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%225.4%22 rx=%222.1%22 ry=%224.4%22 transform=%22rotate%2890.0 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%225.4%22 rx=%222.1%22 ry=%224.4%22 transform=%22rotate%28135.0 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%225.4%22 rx=%222.1%22 ry=%224.4%22 transform=%22rotate%28180.0 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%225.4%22 rx=%222.1%22 ry=%224.4%22 transform=%22rotate%28225.0 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%225.4%22 rx=%222.1%22 ry=%224.4%22 transform=%22rotate%28270.0 12 12%29%22/%3E%3Cellipse cx=%2212%22 cy=%225.4%22 rx=%222.1%22 ry=%224.4%22 transform=%22rotate%28315.0 12 12%29%22/%3E%3C/svg%3E");
  --wu-ic-menu: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Crect x=%224%22 y=%225.4%22 width=%2212%22 height=%222%22 rx=%221%22/%3E%3Ccircle cx=%2219.5%22 cy=%226.4%22 r=%221.6%22/%3E%3Crect x=%224%22 y=%2211%22 width=%2216%22 height=%222%22 rx=%221%22/%3E%3Crect x=%224%22 y=%2216.6%22 width=%229%22 height=%222%22 rx=%221%22/%3E%3Ccircle cx=%2216.5%22 cy=%2217.6%22 r=%221.6%22/%3E%3C/svg%3E");
  --wu-ic-wand: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Cpath d=%22M12 1.5c.5 4.6 1.9 6 6.5 6.5-4.6.5-6 1.9-6.5 6.5-.5-4.6-1.9-6-6.5-6.5 4.6-.5 6-1.9 6.5-6.5z%22/%3E%3Cpath d=%22M18.5 13c.3 2.6 1.1 3.4 3.7 3.7-2.6.3-3.4 1.1-3.7 3.7-.3-2.6-1.1-3.4-3.7-3.7 2.6-.3 3.4-1.1 3.7-3.7z%22/%3E%3Ccircle cx=%226%22 cy=%2218.5%22 r=%221.6%22/%3E%3C/svg%3E");
  --wu-ic-arrow: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Cpath d=%22M4 11h11.2l-4.1-4.1L12.5 5.5 19 12l-6.5 6.5-1.4-1.4 4.1-4.1H4z%22/%3E%3Ccircle cx=%223.5%22 cy=%2212%22 r=%221.4%22/%3E%3C/svg%3E");
  --wu-ic-quill: url("data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22%3E%3Cpath d=%22M20.5 3.5c-7 .5-11.5 5-13 12.5l-2.5 4.5 1 .5 2.4-4.3c7.3-1.3 11.6-5.9 12.1-13.2zM9.6 15.4c1-3.4 3-6.2 6.4-8.2-2 2.6-3.8 5.4-6.4 8.2z%22 fill-rule=%22evenodd%22/%3E%3C/svg%3E");

  /* 官方阴影/发光一律关闭 */
  --shadowWidth: 0 !important;
  --SmartThemeShadowColor: transparent !important;
  --mainFontFamily: var(--wu-font-body);
}

/* ---------- 02 kernel: scrollbar appearance only ---------- */
::-webkit-scrollbar {
  display: none !important;
}
* {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

/* ---------- 03 sky / shell ---------- */
body {
  background-color: var(--wu-sky);
  font-family: var(--wu-font-body);
}
#bg1,
#bg_custom {
  background-image: none !important;
  background-color: var(--wu-sky) !important;
}
#sheld,
#chat {
  background-color: transparent;
  backdrop-filter: none !important;
  box-shadow: none !important;
  border: none !important;
}

/* 开屏：枝头云朵花，只在聊天最上方出现一次，随内容滚走 */
#chat {
  background-image: var(--wu-title), var(--wu-banner);
  background-repeat: no-repeat, no-repeat;
  background-attachment: local, local;
  background-position: left 18px top 26px, right top;
  background-size: 210px auto, min(100%, 640px) auto;
  padding-top: calc(min(100%, 640px) / 3 + 4px);
}

/* ---------- 04 top bar + redrawn icons ---------- */
#top-bar {
  background: var(--wu-sky) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  border: none !important;
}
#top-settings-holder .drawer-icon {
  --wu-ic: var(--wu-ic-daisy);
  opacity: 1 !important;
  color: var(--wu-pale) !important;
  filter: none !important;
  text-shadow: none !important;
  width: 32px;
  height: 32px;
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  padding: 0 !important;
  transition: background-color .25s, color .25s, transform .25s;
}
#top-settings-holder .drawer-icon::before {
  content: "" !important;
  display: block !important;
  width: 21px;
  height: 21px;
  background-color: currentColor;
  -webkit-mask: var(--wu-ic) center / contain no-repeat;
  mask: var(--wu-ic) center / contain no-repeat;
  font-family: inherit !important;
}
#top-settings-holder .drawer-icon.closedIcon:hover {
  color: var(--wu-cloud) !important;
  transform: rotate(-12deg);
}
#top-settings-holder .drawer-icon.openIcon {
  background-color: var(--wu-cloud);
  color: var(--wu-sky) !important;
}
#top-settings-holder .drawer-icon:focus-visible {
  outline: 2px solid var(--wu-cloud);
  outline-offset: 2px;
}
#ai-config-button .drawer-icon { --wu-ic: var(--wu-ic-sliders); }
#sys-settings-button .drawer-icon { --wu-ic: var(--wu-ic-plug); }
#advanced-formatting-button .drawer-icon { --wu-ic: var(--wu-ic-font); }
#WI-SP-button .drawer-icon { --wu-ic: var(--wu-ic-book); }
#user-settings-button .drawer-icon { --wu-ic: var(--wu-ic-sun); }
#backgrounds-button .drawer-icon { --wu-ic: var(--wu-ic-cloud); }
#extensions-settings-button .drawer-icon { --wu-ic: var(--wu-ic-clover); }
#persona-management-button .drawer-icon { --wu-ic: var(--wu-ic-sunflower); }
#rightNavHolder .drawer-icon { --wu-ic: var(--wu-ic-daisy); }

/* ---------- 05 message skeleton ---------- */
#chat .mes[is_system="false"] {
  position: relative;
  padding: var(--wu-gap-top) 10px 4px 10px;
  background: transparent !important;
  border: none !important;
  color: var(--wu-snow);
}
/* 楼层之间：三颗信号点，按楼层轮流点亮 红→黄→绿 */
#chat .mes[is_system="false"]::before {
  content: "";
  position: absolute;
  top: 12px;
  left: 50%;
  width: 29px;
  height: 6px;
  transform: translateX(-50%);
  pointer-events: none;
  --wu-d1: var(--wu-dot-off);
  --wu-d2: var(--wu-dot-off);
  --wu-d3: var(--wu-dot-off);
  background:
    radial-gradient(circle at 3px 3px, var(--wu-d1) 2.5px, transparent 3px),
    radial-gradient(circle at 14.5px 3px, var(--wu-d2) 2.5px, transparent 3px),
    radial-gradient(circle at 26px 3px, var(--wu-d3) 2.5px, transparent 3px);
}
#chat > .mes[is_system="false"]:nth-child(3n+1)::before { --wu-d1: var(--wu-or); }
#chat > .mes[is_system="false"]:nth-child(3n+2)::before { --wu-d2: var(--wu-ye); }
#chat > .mes[is_system="false"]:nth-child(3n)::before { --wu-d3: var(--wu-gr); }

/* 头像槽释放：头像和楼层数据改为相对整层定位 */
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  position: static !important;
  width: 0 !important;
  min-width: 0 !important;
  flex: 0 0 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}
#chat .mes[is_system="false"] > .mes_block {
  position: relative;
  width: 100%;
  min-width: 0;
  padding: 0 6px;
}

/* 头像：真头像嵌进花框中央的洞里 */
#chat .mes[is_system="false"] .avatar {
  position: absolute !important;
  top: calc(var(--wu-gap-top) - 6px);
  width: var(--wu-av-char) !important;
  height: var(--wu-av-char) !important;
  border-radius: 0 !important;
  background: transparent !important;
  overflow: visible !important;
  z-index: 2;
  flex: none;
}
#chat .mes[is_system="false"] .avatar img {
  position: absolute;
  object-fit: cover;
  border: none !important;
  box-shadow: none !important;
  border-radius: 50% !important;
  background: var(--wu-pale);
}
#chat .mes[is_system="false"] .avatar::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: center / 100% 100% no-repeat;
  transform-origin: 50% 78%;
}
#chat .mes[is_system="false"] .avatar:focus-visible {
  outline: 2px solid var(--wu-cloud);
  outline-offset: 2px;
  border-radius: 50% !important;
}

/* 角色：头像在右，小菊从框底开出 */
#chat .mes[is_user="false"][is_system="false"] .avatar {
  right: 8px;
}
#chat .mes[is_user="false"][is_system="false"] .avatar img {
  left: 16.1%;
  top: 10.0%;
  width: 65.3% !important;
  height: 65.3% !important;
}
#chat .mes[is_user="false"][is_system="false"] .avatar::after {
  background-image: var(--wu-frame-char);
}

/* 你：头像在左，向日葵在下面托住 */
#chat .mes[is_user="true"][is_system="false"] .avatar {
  left: 4px;
  width: var(--wu-av-user) !important;
  height: var(--wu-av-user) !important;
}
#chat .mes[is_user="true"][is_system="false"] .avatar img {
  left: 24.4%;
  top: 9.4%;
  width: 51% !important;
  height: 51% !important;
}
#chat .mes[is_user="true"][is_system="false"] .avatar::after {
  background-image: var(--wu-frame-user);
}

/* 只有最新一层播放开花，旧楼层静止 */
#chat .mes.last_mes[is_system="false"] .avatar::after {
  animation: wu-bloom 1.1s cubic-bezier(.3, 1.4, .5, 1) both;
}
@keyframes wu-bloom {
  0% { transform: scale(.55); opacity: 0; }
  55% { opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  #chat .mes.last_mes .avatar::after { animation: none; }
}
body.reduced-motion #chat .mes.last_mes .avatar::after { animation: none; }

/* ---------- 06 message header (poster card) ---------- */
#chat .mes[is_system="false"] .ch_name {
  align-items: flex-start !important;
  font-weight: 400;
}
#chat .mes[is_user="false"][is_system="false"] .ch_name {
  min-height: var(--wu-head-char);
  padding-right: calc(var(--wu-av-char) + 2px);
}
#chat .mes[is_user="true"][is_system="false"] .ch_name {
  min-height: var(--wu-head-user);
  padding-left: calc(var(--wu-av-user) + 4px);
}
#chat .mes[is_system="false"] .ch_name .alignItemsBaseline {
  flex-direction: column;
  flex-wrap: nowrap;
  align-items: flex-start !important;
  gap: 2px;
  min-width: 0;
  max-width: 100%;
}

/* 名字胶囊 */
#chat .mes[is_system="false"] .name_text {
  display: inline-block;
  background: var(--wu-cloud) var(--wu-st-daisy-o) 6px center / 18px 18px no-repeat;
  color: var(--wu-ink) !important;
  font-family: var(--wu-font-title);
  font-size: calc(var(--mainFontSize) * .88);
  font-weight: 600;
  letter-spacing: .08em;
  line-height: 1.5;
  padding: 3px 14px 3px 30px;
  border-radius: 14px;
  text-shadow: none !important;
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  box-sizing: border-box;
}
#chat .mes[is_user="true"][is_system="false"] .name_text {
  background-image: var(--wu-st-sunflower);
}
#chat .mes[is_system="false"] .timestamp {
  font-family: var(--wu-font-latin);
  font-style: italic;
  font-size: calc(var(--mainFontSize) * .82);
  color: var(--wu-pale);
  opacity: 1;
  letter-spacing: .04em;
  padding-left: 6px;
  white-space: nowrap;
}

/* 海报标题（装饰层，不挡交互） */
#chat .mes[is_system="false"] > .mes_block::before {
  position: absolute;
  top: 54px;
  pointer-events: none;
  white-space: pre;
  font-family: var(--wu-font-title);
  font-size: calc(var(--mainFontSize) * 1.65);
  line-height: 1.15;
  letter-spacing: .1em;
  color: var(--wu-snow);
}
#chat .mes[is_user="false"][is_system="false"] > .mes_block::before {
  content: "停一停";
  left: 6px;
}
#chat .mes[is_user="true"][is_system="false"] > .mes_block::before {
  content: "向阳";
  left: calc(var(--wu-av-user) + 10px);
  font-size: calc(var(--mainFontSize) * 1.35);
}
#chat .mes[is_system="false"] > .mes_block::after {
  position: absolute;
  top: 88px;
  pointer-events: none;
  font-family: var(--wu-font-latin);
  font-style: italic;
  font-size: calc(var(--mainFontSize) * .95);
  color: var(--wu-pale);
  letter-spacing: .03em;
  padding-bottom: 6px;
  background: linear-gradient(90deg, var(--wu-mid) 50%, transparent 0) left bottom / 4px 1px repeat-x;
}
#chat .mes[is_user="false"][is_system="false"] > .mes_block::after {
  content: "red light, in bloom";
  left: 6px;
  width: 150px;
}
#chat .mes[is_user="true"][is_system="false"] > .mes_block::after {
  content: "facing the sun";
  top: 82px;
  left: calc(var(--wu-av-user) + 10px);
  width: 120px;
}

/* 楼层 / 耗时 / token：三颗信号灯 */
#chat .mes[is_system="false"] .mesIDDisplay,
#chat .mes[is_system="false"] .mes_timer,
#chat .mes[is_system="false"] .tokenCounterDisplay {
  position: absolute;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 22px;
  padding: 0 10px 0 8px;
  border-radius: 11px;
  background: var(--wu-cloud);
  color: var(--wu-ink);
  font-family: var(--wu-font-latin);
  font-style: italic;
  font-weight: 500;
  font-size: calc(var(--mainFontSize) * .85);
  opacity: 1 !important;
  white-space: nowrap;
}
#chat .mes[is_system="false"] .mesIDDisplay:empty,
#chat .mes[is_system="false"] .mes_timer:empty,
#chat .mes[is_system="false"] .tokenCounterDisplay:empty {
  display: none;
}
#chat .mes[is_system="false"] .mesIDDisplay::before,
#chat .mes[is_system="false"] .mes_timer::before,
#chat .mes[is_system="false"] .tokenCounterDisplay::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: none;
}
#chat .mes[is_system="false"] .mesIDDisplay::before { background: var(--wu-or); }
#chat .mes[is_system="false"] .mes_timer::before { background: var(--wu-ye); }
#chat .mes[is_system="false"] .tokenCounterDisplay::before { background: var(--wu-gr); }

#chat .mes[is_user="false"][is_system="false"] .mesIDDisplay { top: calc(var(--wu-gap-top) + 120px); left: 16px; }
#chat .mes[is_user="false"][is_system="false"] .mes_timer { top: calc(var(--wu-gap-top) + 120px); left: 72px; }
#chat .mes[is_user="false"][is_system="false"] .tokenCounterDisplay { top: calc(var(--wu-gap-top) + 148px); left: 16px; }
#chat .mes[is_user="true"][is_system="false"] .mesIDDisplay { top: calc(var(--wu-gap-top) + 112px); left: calc(var(--wu-av-user) + 20px); }
#chat .mes[is_user="true"][is_system="false"] .mes_timer { top: calc(var(--wu-gap-top) + 112px); left: calc(var(--wu-av-user) + 76px); }
#chat .mes[is_user="true"][is_system="false"] .tokenCounterDisplay { top: calc(var(--wu-gap-top) + 112px); left: calc(var(--wu-av-user) + 140px); }
#chat .mes[is_user="true"][is_system="false"] .mes_timer:empty + .tokenCounterDisplay { left: calc(var(--wu-av-user) + 76px); }

/* 消息操作：淡蓝，不发光 */
#chat .mes .mes_button,
#chat .mes .extraMesButtons > div,
#chat .mes .swipe_left,
#chat .mes .swipe_right,
#chat .mes .mes_ghost {
  color: var(--wu-line) !important;
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
}
#chat .mes .mes_button:hover,
#chat .mes .extraMesButtons > div:hover,
#chat .mes .swipe_left:hover,
#chat .mes .swipe_right:hover {
  color: var(--wu-cloud) !important;
}
#chat .mes .mes_button:focus-visible,
#chat .mes .extraMesButtons > div:focus-visible {
  outline: 1px solid var(--wu-cloud);
  border-radius: 6px;
}
#chat .mes .swipes-counter {
  color: var(--wu-pale);
  font-family: var(--wu-font-latin);
  font-style: italic;
  opacity: 1;
}
#chat .mes.lastInContext {
  border-top: none !important;
}
#chat .mes.lastInContext::after {
  content: "上下文到此为止 · 再往上的花，模型看不见";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, -2px);
  font-family: var(--wu-font-title);
  font-size: 11px;
  letter-spacing: .1em;
  color: var(--wu-pale);
  pointer-events: none;
  white-space: nowrap;
}

/* ---------- 07 message text layering ---------- */
#chat .mes[is_system="false"] .mes_text {
  font-family: var(--wu-font-body);
  font-size: var(--mainFontSize);
  line-height: 1.95;
  letter-spacing: .06em;
  color: var(--wu-snow);
  padding: 4px 12px 6px 6px;
  text-shadow: none !important;
}
#chat .mes[is_user="true"][is_system="false"] .mes_text {
  color: var(--wu-pale);
}
#chat .mes .mes_text p {
  margin: 0 0 .7em;
}
#chat .mes .mes_text q {
  color: var(--wu-ink);
  background: var(--wu-cloud);
  border-radius: 12px;
  padding: 2px 10px;
  -webkit-box-decoration-break: clone;
  box-decoration-break: clone;
}
#chat .mes .mes_text q::before,
#chat .mes .mes_text q::after {
  content: none;
}
#chat .mes .mes_text em,
#chat .mes .mes_text i:not([class*="fa-"]) {
  font-style: normal;
  color: var(--wu-cream);
}
#chat .mes .mes_text q em {
  color: var(--wu-ink-soft);
}
#chat .mes .mes_text strong,
#chat .mes .mes_text b {
  font-weight: 600;
  text-decoration: underline wavy var(--wu-ye) 1px;
  text-underline-offset: 5px;
}
#chat .mes .mes_text u {
  text-decoration: underline dotted var(--wu-cream) 1.5px;
  text-underline-offset: 4px;
}
#chat .mes .mes_text blockquote {
  margin: .6em 0;
  padding: 8px 14px;
  border: 1px dashed var(--wu-mid) !important;
  border-radius: 16px;
  background: var(--wu-glass);
  color: var(--wu-pale);
}
#chat .mes .mes_text hr {
  border: none;
  height: 6px;
  opacity: 1;
  background:
    radial-gradient(circle, var(--wu-mid) 1.6px, transparent 2px) center / 14px 6px repeat-x;
  margin: 1em 20%;
}
#chat .mes .mes_text a {
  color: var(--wu-cream);
  text-decoration: underline dotted;
}
#chat .mes .mes_text code {
  font-family: ui-monospace, Menlo, Consolas, monospace;
  background: var(--wu-glass);
  color: var(--wu-snow);
  border-radius: 6px;
  padding: 1px 6px;
  border: none;
}
#chat .mes .mes_text pre {
  background: var(--wu-ink) !important;
  border-radius: 14px;
  border: none;
  padding: 10px 12px;
  overflow-x: auto;
}
#chat .mes .mes_text pre code,
#chat .mes .mes_text pre code.hljs {
  background: transparent !important;
  padding: 0;
  color: var(--wu-snow);
}
#chat .mes .mes_text ::selection,
#send_textarea::selection {
  background: var(--wu-ye);
  color: var(--wu-ink);
}

/* 思考块 */
#chat .mes .mes_reasoning_details {
  border: 1px dashed var(--wu-mid);
  border-radius: 16px;
  background: var(--wu-glass);
  padding: 4px 12px;
  margin: 4px 0 8px;
}
#chat .mes .mes_reasoning_summary,
#chat .mes .mes_reasoning_header_title,
#chat .mes .mes_reasoning_arrow {
  color: var(--wu-pale) !important;
  font-family: var(--wu-font-title);
  font-size: calc(var(--mainFontSize) * .85);
  opacity: 1;
}
#chat .mes .mes_reasoning {
  color: var(--wu-pale);
  font-size: calc(var(--mainFontSize) * .9);
  border: none !important;
}

/* 编辑态 */
#chat .mes .edit_textarea,
#chat .mes .reasoning_edit_textarea {
  background: var(--wu-cloud) !important;
  color: var(--wu-ink) !important;
  border: 1px solid var(--wu-line) !important;
  border-radius: 14px !important;
  font-family: var(--wu-font-body);
  line-height: 1.8;
  padding: 8px 12px;
}
#chat .mes .mes_edit_buttons .menu_button {
  background: var(--wu-cloud);
  color: var(--wu-ink);
  border: none;
  border-radius: 50%;
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  filter: none !important;
  opacity: 1;
}
#chat .mes .mes_edit_buttons .mes_edit_delete {
  color: var(--wu-or);
}

/* 系统消息 */
#chat .mes[is_system="true"] .mes_text {
  color: var(--wu-pale);
  font-family: var(--wu-font-body);
}

/* ---------- 08 input bar ---------- */
#form_sheld,
#send_form {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}
#send_form {
  padding: 6px 8px 10px;
  gap: 6px;
}
#nonQRFormItems {
  align-items: center;
  gap: 6px;
}
#send_textarea {
  background: var(--wu-cloud) !important;
  color: var(--wu-ink) !important;
  border-radius: 20px !important;
  padding: 9px 16px !important;
  font-family: var(--wu-font-body);
  font-size: var(--mainFontSize);
  line-height: 1.6;
  box-shadow: none !important;
}
#send_textarea::placeholder {
  color: var(--wu-hint);
  opacity: 1;
}
#send_textarea:focus-visible {
  outline: 2px solid var(--wu-ye);
  outline-offset: 0;
}

/* 输入栏所有按钮：去掉官方灰度与透明 */
#leftSendForm > div,
#rightSendForm > div {
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
  color: var(--wu-cloud) !important;
  border-radius: 50%;
}
#leftSendForm > div:hover,
#rightSendForm > div:hover {
  filter: none !important;
  transform: rotate(-10deg);
}
#leftSendForm > div:focus-visible,
#rightSendForm > div:focus-visible {
  outline: 2px solid var(--wu-cloud);
  outline-offset: 1px;
}

/* 画线图标：关掉旧字形，换新遮罩图 */
#options_button,
#extensionsMenuButton,
#mes_continue,
#mes_impersonate {
  --wu-ic: var(--wu-ic-menu);
  border: 1px solid var(--wu-pale) !important;
  box-sizing: border-box;
  transition: transform .25s, background-color .25s;
}
#extensionsMenuButton { --wu-ic: var(--wu-ic-wand); }
#mes_continue { --wu-ic: var(--wu-ic-arrow); }
#mes_impersonate { --wu-ic: var(--wu-ic-quill); }
#options_button::before,
#extensionsMenuButton::before,
#mes_continue::before,
#mes_impersonate::before {
  content: "" !important;
  display: block;
  width: 18px;
  height: 18px;
  background-color: currentColor;
  -webkit-mask: var(--wu-ic) center / contain no-repeat;
  mask: var(--wu-ic) center / contain no-repeat;
  font-family: inherit !important;
}

/* 发送：一朵向日葵 */
#send_but {
  background: var(--wu-cloud) !important;
  border: none !important;
  transition: transform .4s cubic-bezier(.3, 1.4, .5, 1);
}
#send_but::before {
  content: "" !important;
  display: block;
  width: 78%;
  height: 78%;
  background: var(--wu-st-sunflower) center / contain no-repeat;
  font-family: inherit !important;
}
#send_but:hover {
  transform: rotate(40deg);
}
#send_but:active {
  transform: rotate(80deg) scale(.92);
}

/* 停止：橙菊在转，等一个红灯 */
#mes_stop {
  opacity: 1 !important;
  filter: none !important;
  background: var(--wu-cloud) !important;
  border-radius: 50%;
  width: var(--bottomFormBlockSize);
  height: var(--bottomFormBlockSize);
  align-items: center;
  justify-content: center;
}
#mes_stop > i {
  width: 78%;
  height: 78%;
  display: block;
  background: var(--wu-st-daisy-o) center / contain no-repeat;
  animation: wu-spin 3.2s linear infinite;
}
#mes_stop > i::before {
  content: "" !important;
}
@keyframes wu-spin {
  to { transform: rotate(360deg); }
}
body.reduced-motion #mes_stop > i { animation: none; }

/* 脚本按钮 */
#rightSendForm > .stscript_btn > .fa-solid {
  background-color: var(--wu-cloud) !important;
  color: var(--wu-sky) !important;
}

/* ---------- 09 shared panels: drawers / floating / popups ---------- */
.drawer-content,
#right-nav-panel,
#left-nav-panel,
.draggable,
dialog.popup,
.popup,
#extensionsMenu,
.options-content,
.list-group,
.select2-dropdown {
  --SmartThemeBodyColor: #1E3F73;
  --SmartThemeEmColor: #4A6FA8;
  --SmartThemeQuoteColor: #2F6CC4;
  --SmartThemeUnderlineColor: #2F6CC4;
  --SmartThemeBorderColor: #BFD6F5;
  --SmartThemeBlurTintColor: #FFFFFF;
  --SmartThemeCheckboxTickColor: #FFFFFF;
  --interactable-outline-color: #3B7DD8;
  --mainFontFamily: var(--wu-font-title);
  color: var(--wu-ink);
  font-family: var(--wu-font-title);
}
.drawer-content,
#right-nav-panel,
#left-nav-panel,
.draggable {
  background-color: var(--wu-panel) !important;
  background-image: linear-gradient(180deg, var(--wu-panel-top) 0, var(--wu-panel) 220px) !important;
  border: none !important;
  border-radius: 22px !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}
.drawer-content h3,
.drawer-content h4,
.draggable h3,
.draggable h4 {
  font-family: var(--wu-font-title);
  font-weight: 600;
  letter-spacing: .06em;
  color: var(--wu-ink);
}

/* 菜单弹出（输入栏左侧菜单 / 扩展菜单） */
.options-content,
#extensionsMenu,
.list-group {
  background: var(--wu-cloud) !important;
  border: 1px solid var(--wu-line) !important;
  border-radius: 18px !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  padding: 6px !important;
}
.options-content a,
.options-content .menu_button,
#extensionsMenu .list-group-item,
.list-group .list-group-item {
  color: var(--wu-ink) !important;
  border-radius: 12px;
  opacity: 1 !important;
  filter: none !important;
  background: transparent;
}
.options-content a:hover,
#extensionsMenu .list-group-item:hover,
.list-group .list-group-item:hover {
  background: var(--wu-mist) !important;
}

/* 文本框 / 下拉 / 数字 */
:is(.drawer-content, .draggable, .popup, #character_popup, #right-nav-panel, #left-nav-panel) :is(.text_pole, select, textarea, input[type="text"], input[type="number"], input[type="search"], input[type="password"], input[type="url"]) {
  background-color: var(--wu-cloud) !important;
  color: var(--wu-ink) !important;
  border: 1px solid var(--wu-line) !important;
  border-radius: 12px !important;
  box-shadow: none !important;
}
:is(.drawer-content, .draggable, .popup, #character_popup, #right-nav-panel, #left-nav-panel) :is(.text_pole, select, textarea, input[type="text"], input[type="number"], input[type="search"]):not([class*="fa-"]) {
  font-family: var(--wu-font-title);
}
:is(.drawer-content, .draggable, .popup, #right-nav-panel, #left-nav-panel) :is(.text_pole, textarea, input)::placeholder {
  color: var(--wu-hint) !important;
  opacity: 1;
}
:is(.drawer-content, .draggable, .popup, #right-nav-panel, #left-nav-panel) :is(.text_pole, select, textarea, input):focus-visible {
  outline: 2px solid var(--wu-sky) !important;
  outline-offset: 0;
}
select option {
  background: var(--wu-cloud);
  color: var(--wu-ink);
}

/* 通用按钮 */
.menu_button {
  background-color: var(--wu-cloud) !important;
  color: var(--wu-ink) !important;
  border: 1px solid var(--wu-line) !important;
  border-radius: 14px !important;
  filter: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
  word-break: keep-all;
  opacity: 1;
}
/* 只给纯文字按钮换字体；带 fa- 的图标按钮保留 Font Awesome 字形 */
.menu_button:not([class*="fa-"]) {
  font-family: var(--wu-font-title);
}
.menu_button:hover {
  background-color: var(--wu-mist) !important;
  border-color: var(--wu-mid) !important;
}
.menu_button:focus-visible {
  outline: 2px solid var(--wu-sky);
  outline-offset: 1px;
}
.menu_button.toggleEnabled,
.menu_button.active,
.popup-button-ok.menu_button,
#rm_button_create.menu_button {
  background-color: var(--wu-sky) !important;
  color: var(--wu-cloud) !important;
  border-color: var(--wu-sky) !important;
}
.menu_button.disabled,
.menu_button:disabled {
  background-color: var(--wu-mist) !important;
  color: var(--wu-hint) !important;
  border-color: var(--wu-pale) !important;
  cursor: not-allowed;
}
.menu_button.caution,
.menu_button.redWarningBG,
.menu_button.redOverlayGlow {
  background-color: var(--wu-or) !important;
  border-color: var(--wu-or) !important;
  color: var(--wu-cloud) !important;
}

/* 面板里的 Font Awesome 小图标：不发光、不发灰 */
.drawer-content .fa-solid,
.drawer-content .fa-regular,
.popup .fa-solid,
.popup .fa-regular,
.draggable .fa-solid,
.welcomePanel .fa-solid,
.welcomePanel .fa-regular {
  text-shadow: none !important;
  filter: none !important;
}
.drawer-content .right_menu_button,
.drawer-content .inline-drawer-icon,
.drawer-content .interactable,
.welcomePanel .menu_button,
.welcomePanel .interactable {
  filter: none !important;
  opacity: 1 !important;
  text-shadow: none !important;
}

/* 复选框（保留官方勾的生成链，只换颜色） */
input[type="checkbox"] {
  background-color: var(--wu-cloud) !important;
  outline: 1px solid var(--wu-mid) !important;
  border-radius: 5px !important;
  box-shadow: none !important;
}
input[type="checkbox"]:checked {
  background-color: var(--wu-sky) !important;
  outline-color: var(--wu-sky) !important;
}
input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--wu-ye) !important;
}
input[type="radio"] {
  accent-color: var(--wu-sky);
}

/* 滑块：拖柄是一朵向日葵 */
input[type="range"] {
  background-color: var(--wu-pale) !important;
  background-image: linear-gradient(var(--wu-sky), var(--wu-sky)) !important;
  height: 4px;
  border-radius: 2px;
  filter: none !important;
}
input[type="range"]:hover {
  filter: none !important;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 24px;
  height: 24px;
  border: none !important;
  border-radius: 50%;
  background: var(--wu-st-sunflower) center / contain no-repeat !important;
  box-shadow: none !important;
}
input[type="range"]::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border: none;
  border-radius: 50%;
  background: var(--wu-st-sunflower) center / contain no-repeat;
}
input[type="range"]:focus-visible {
  outline: 2px solid var(--wu-sky) !important;
  outline-offset: 4px;
}

/* ---------- 10 extension headers: 灰色渐变全部换掉 ---------- */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
  background-image: none !important;
  background-color: var(--wu-cloud) !important;
  color: var(--wu-ink) !important;
  border: 1px solid var(--wu-pale) !important;
  border-radius: 16px !important;
  padding: 7px 12px 7px 36px !important;
  box-shadow: none !important;
  filter: none !important;
  font-family: var(--wu-font-title);
  letter-spacing: .04em;
  position: relative;
}
#extensions_settings .inline-drawer-toggle.inline-drawer-header::before,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header::before,
#user-settings-block h4::before,
.standoutHeader::before {
  content: "";
  position: absolute;
  left: 10px;
  top: 50%;
  width: 18px;
  height: 18px;
  transform: translateY(-50%);
  pointer-events: none;
  background: var(--wu-st-daisy-o) center / contain no-repeat;
}
#extensions_settings > :nth-child(3n+2) .inline-drawer-toggle.inline-drawer-header::before,
#extensions_settings2 > :nth-child(3n+2) .inline-drawer-toggle.inline-drawer-header::before {
  background-image: var(--wu-st-daisy-y);
}
#extensions_settings > :nth-child(3n) .inline-drawer-toggle.inline-drawer-header::before,
#extensions_settings2 > :nth-child(3n) .inline-drawer-toggle.inline-drawer-header::before {
  background-image: var(--wu-st-clover);
}
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
.standoutHeader.inline-drawer-header:hover {
  filter: none !important;
  background-color: var(--wu-mist) !important;
  border-color: var(--wu-mid) !important;
}
#extensions_settings .inline-drawer-header b,
#extensions_settings2 .inline-drawer-header b,
#extensions_settings .inline-drawer-icon,
#extensions_settings2 .inline-drawer-icon {
  color: var(--wu-ink) !important;
  opacity: 1 !important;
}
.inline-drawer-content {
  color: var(--wu-ink);
}

/* ---------- 11 popups ---------- */
dialog.popup,
.popup {
  background-color: var(--wu-panel) !important;
  background-image: var(--wu-st-daisy-o), var(--wu-st-daisy-y), var(--wu-st-clover) !important;
  background-repeat: no-repeat !important;
  background-size: 24px 24px, 28px 28px, 22px 22px !important;
  background-position: calc(50% - 30px) 14px, 50% 12px, calc(50% + 29px) 15px !important;
  padding-top: 46px !important;
  border: none !important;
  border-radius: 24px !important;
  box-shadow: none !important;
  color: var(--wu-ink) !important;
}
dialog.popup::backdrop {
  background: var(--wu-veil);
  backdrop-filter: none;
}
.popup .popup-controls .menu_button {
  min-width: 96px;
}
.popup .popup-button-cancel.menu_button {
  background-color: var(--wu-cloud) !important;
  color: var(--wu-ink) !important;
}
.popup h3,
.popup h4 {
  color: var(--wu-ink);
  font-family: var(--wu-font-title);
}

/* 历史聊天列表 / 角色列表：浅底深字，看得清 */
.select_chat_block,
.select_chat_block_wrapper .select_chat_block {
  background-color: var(--wu-cloud) !important;
  color: var(--wu-ink) !important;
  border: 1px solid var(--wu-pale) !important;
  border-radius: 16px !important;
  box-shadow: none !important;
}
.select_chat_block:hover,
.select_chat_block[highlight="true"] {
  background-color: var(--wu-mist) !important;
  border-color: var(--wu-mid) !important;
}
.select_chat_block .select_chat_block_filename,
.select_chat_block .select_chat_block_mes,
.select_chat_block .chat_messages_num,
.select_chat_block .chat_file_size,
.select_chat_block small {
  color: var(--wu-ink-soft) !important;
  opacity: 1 !important;
}
/* 标签 */
.tag,
.tags .tag {
  background-color: var(--wu-pale) !important;
  color: var(--wu-ink) !important;
  border: none !important;
  border-radius: 10px !important;
  filter: none !important;
  opacity: 1;
}
.tag.selected {
  background-color: var(--wu-sky) !important;
  color: var(--wu-cloud) !important;
}
.tag.excluded {
  background-color: var(--wu-or) !important;
  color: var(--wu-cloud) !important;
}
.tag .tag_remove {
  color: inherit;
  opacity: .8;
}

/* Select2 */
.select2-container .select2-selection,
.select2-container--default .select2-selection--multiple,
.select2-container--default .select2-selection--single {
  background-color: var(--wu-mist) !important;
  border: 1px solid var(--wu-line) !important;
  border-radius: 12px !important;
  color: var(--wu-ink) !important;
}
.select2-container--default .select2-selection--multiple .select2-selection__choice {
  background-color: var(--wu-pale) !important;
  color: var(--wu-ink) !important;
  border: none !important;
  border-radius: 10px !important;
}
.select2-dropdown {
  background-color: var(--wu-cloud) !important;
  border: 1px solid var(--wu-line) !important;
  border-radius: 14px !important;
  color: var(--wu-ink) !important;
}
.select2-results__option {
  color: var(--wu-ink) !important;
}
.select2-results__option--highlighted,
.select2-container--default .select2-results__option--highlighted[aria-selected] {
  background-color: var(--wu-pale) !important;
  color: var(--wu-ink) !important;
}

/* 通知 */
#toast-container > .toast,
#toast-container > div {
  background-color: var(--wu-cloud) !important;
  color: var(--wu-ink) !important;
  border: 1px solid var(--wu-line) !important;
  border-radius: 16px !important;
  box-shadow: none !important;
  opacity: 1 !important;
  font-family: var(--wu-font-title);
}
#toast-container > .toast-error {
  border-color: var(--wu-or) !important;
}
#toast-container > .toast-warning {
  border-color: var(--wu-ye) !important;
}
#toast-container > .toast-success {
  border-color: var(--wu-gr) !important;
}
#toast-container .toast-title {
  color: var(--wu-ink) !important;
}

/* 欢迎页 */
.welcomePanel,
.welcomeRecent .recentChat {
  color: var(--wu-snow);
}
.welcomeRecent .recentChat {
  background: var(--wu-glass) !important;
  border: 1px dashed var(--wu-mid) !important;
  border-radius: 16px !important;
}
.welcomeRecent .recentChat:hover {
  background: rgba(255, 255, 255, .22) !important;
}

/* ---------- 11b lists: persona / characters / prompt manager ---------- */
/* 人设、角色：白卡片 + 花徽章 */
#user_avatar_block .avatar-container,
#rm_print_characters_block .character_select,
#rm_print_characters_block .group_select,
#rm_print_characters_block .bogus_folder_select {
  background-color: var(--wu-cloud) !important;
  border: 1px solid var(--wu-pale) !important;
  border-radius: 18px !important;
  padding: 8px 10px !important;
  margin: 5px 2px !important;
  box-shadow: none !important;
  color: var(--wu-ink);
  transition: border-color .2s, background-color .2s;
}
#user_avatar_block .avatar-container:hover,
#rm_print_characters_block .character_select:hover,
#rm_print_characters_block .group_select:hover,
#rm_print_characters_block .bogus_folder_select:hover {
  background-color: var(--wu-mist) !important;
  border-color: var(--wu-mid) !important;
}
#user_avatar_block .avatar-container.selected {
  border: 2px solid var(--wu-sky) !important;
  background-color: var(--wu-mist) !important;
}
#user_avatar_block .avatar-container .avatar,
#rm_print_characters_block .character_select .avatar,
#rm_print_characters_block .group_select .avatar {
  position: relative;
  overflow: visible !important;
  outline: none !important;
  border-radius: 50% !important;
}
#user_avatar_block .avatar-container .avatar img,
#rm_print_characters_block .character_select .avatar img,
#rm_print_characters_block .group_select .avatar img {
  border: none !important;
  box-shadow: 0 0 0 2px var(--wu-pale) !important;
  border-radius: 50% !important;
}
#user_avatar_block .avatar-container.selected .avatar img {
  box-shadow: 0 0 0 2px var(--wu-sky) !important;
}
#user_avatar_block .avatar-container.default_persona .avatar img {
  box-shadow: 0 0 0 2px var(--wu-ye) !important;
}
#user_avatar_block .avatar-container .avatar::after,
#rm_print_characters_block .character_select .avatar::after {
  content: "";
  position: absolute;
  right: -5px;
  bottom: -4px;
  width: 20px;
  height: 20px;
  pointer-events: none;
  background: var(--wu-st-daisy-o) center / contain no-repeat;
}
#user_avatar_block .avatar-container .avatar::after {
  background-image: var(--wu-st-sunflower);
}
#user_avatar_block .avatar-container.selected .avatar::after {
  width: 26px;
  height: 26px;
  right: -8px;
  bottom: -7px;
}
#rm_print_characters_block > .character_select:nth-child(3n+2) .avatar::after { background-image: var(--wu-st-daisy-y); }
#rm_print_characters_block > .character_select:nth-child(3n) .avatar::after { background-image: var(--wu-st-clover); }
#user_avatar_block .avatar-container .ch_name,
#rm_print_characters_block .character_select .ch_name,
#rm_print_characters_block .group_select .ch_name {
  color: var(--wu-ink) !important;
  font-family: var(--wu-font-title);
  font-weight: 600;
  letter-spacing: .04em;
}
#user_avatar_block .avatar-container.selected .ch_name::after {
  content: "当前";
  display: inline-block;
  margin-left: 6px;
  padding: 0 7px;
  border-radius: 8px;
  background: var(--wu-ye);
  color: var(--wu-ink);
  font-size: 11px;
  font-weight: 400;
  line-height: 1.6;
  vertical-align: 2px;
}
#user_avatar_block .avatar-container .ch_description,
#user_avatar_block .avatar-container .ch_additional_info,
#rm_print_characters_block .character_select .ch_description,
#rm_print_characters_block .character_select .ch_additional_info,
#rm_print_characters_block .group_select .ch_description {
  color: var(--wu-hint) !important;
  opacity: 1 !important;
}

/* 提示词条目：开着的是白卡片，关着的是虚线框，字仍然看得清 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background-color: var(--wu-cloud) !important;
  border: 1px solid var(--wu-pale) !important;
  border-radius: 14px !important;
  margin: 5px 0;
  color: var(--wu-ink);
  opacity: 1 !important;
  filter: none !important;
}
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background-color: transparent !important;
  border: 1px dashed var(--wu-mid) !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: var(--wu-ink) !important;
  opacity: 1 !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: var(--wu-hint) !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
  color: var(--wu-mid) !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .fa-solid,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .fa-regular {
  color: var(--wu-ink-soft);
  opacity: 1 !important;
  filter: none !important;
  text-shadow: none !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .prompt-manager-detach-action,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .fa-trash,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .fa-trash-can {
  color: var(--wu-or) !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .prompt-manager-toggle-action {
  color: var(--wu-sky) !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .prompt-manager-toggle-action {
  color: var(--wu-mid) !important;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .prompt_manager_prompt_tokens,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt [class*="tokens"] {
  color: var(--wu-ink-soft) !important;
  font-family: ui-monospace, Menlo, Consolas, monospace;
  opacity: 1 !important;
}
#completion_prompt_manager .completion_prompt_manager_list_head,
#completion_prompt_manager .completion_prompt_manager_footer {
  color: var(--wu-ink-soft);
}

/* 面板里的代码片段：去掉灰黑底 */
:is(.drawer-content, .draggable, .popup, #right-nav-panel, #left-nav-panel) code {
  background-color: var(--wu-cloud) !important;
  color: var(--wu-sky-deep) !important;
  border: 1px solid var(--wu-line);
  border-radius: 8px;
  padding: 0 6px;
}
:is(.drawer-content, .draggable, .popup) pre {
  background-color: var(--wu-cloud) !important;
  border: 1px solid var(--wu-line) !important;
  border-radius: 12px;
}
:is(.drawer-content, .draggable, .popup) pre code {
  border: none;
}

/* 已选世界书 / 标签选择里的灰色 ✕ */
.select2-container .select2-selection--multiple .select2-selection__choice__remove,
.select2-container .select2-selection--single .select2-selection__choice__remove {
  background-color: transparent !important;
  color: var(--wu-ink-soft) !important;
  border: none !important;
  opacity: 1 !important;
}
.select2-container .select2-selection--multiple .select2-selection__choice__remove:hover {
  color: var(--wu-or) !important;
}
.select2-container .select2-search__field {
  color: var(--wu-ink) !important;
  background: transparent !important;
}

/* ---------- 12 mobile ---------- */
@media (max-width: 700px) {
  :root {
    --wu-av-char: 132px;
    --wu-av-user: 112px;
    --wu-head-char: 160px;
    --wu-head-user: 130px;
    --wu-gap-top: 30px;
  }
  #chat {
    background-size: 168px auto, 100% auto;
    background-position: left 14px top 18px, right top;
    padding-top: calc(100vw / 3 + 2px);
  }
  #top-settings-holder .drawer-icon {
    width: 30px;
    height: 30px;
  }
  #top-settings-holder .drawer-icon::before {
    width: 19px;
    height: 19px;
  }
  #chat .mes[is_system="false"] > .mes_block::before {
    top: 52px;
    font-size: calc(var(--mainFontSize) * 1.35);
  }
  #chat .mes[is_user="true"][is_system="false"] > .mes_block::before {
    font-size: calc(var(--mainFontSize) * 1.15);
  }
  #chat .mes[is_system="false"] > .mes_block::after {
    top: 80px;
    font-size: calc(var(--mainFontSize) * .85);
  }
  #chat .mes[is_user="true"][is_system="false"] > .mes_block::after {
    top: 76px;
  }
  #chat .mes[is_user="false"][is_system="false"] .mesIDDisplay { top: calc(var(--wu-gap-top) + 108px); left: 14px; }
  #chat .mes[is_user="false"][is_system="false"] .mes_timer { top: calc(var(--wu-gap-top) + 108px); left: 68px; }
  #chat .mes[is_user="false"][is_system="false"] .tokenCounterDisplay { top: calc(var(--wu-gap-top) + 134px); left: 14px; }
  #chat .mes[is_user="true"][is_system="false"] .mesIDDisplay { top: calc(var(--wu-gap-top) + 102px); left: calc(var(--wu-av-user) + 16px); }
  #chat .mes[is_user="true"][is_system="false"] .mes_timer { top: calc(var(--wu-gap-top) + 102px); left: calc(var(--wu-av-user) + 70px); }
  #chat .mes[is_user="true"][is_system="false"] .tokenCounterDisplay { top: calc(var(--wu-gap-top) + 102px); left: calc(var(--wu-av-user) + 124px); }
  #chat .mes[is_user="true"][is_system="false"] .mes_timer:empty + .tokenCounterDisplay { left: calc(var(--wu-av-user) + 70px); }
  #chat .mes[is_system="false"] .mes_text {
    padding-right: 4px;
  }
  .drawer-content,
  #right-nav-panel,
  #left-nav-panel {
    border-radius: 0 0 22px 22px !important;
  }
}
